    resourceArgv: ['--network', 'none', '--read-only'],
    command: ['/bin/worker'],
    accelerator: 'cpu',
    ...overrides,
  }
}

function cudaRequest(overrides: Partial<WorkerLaunchRequest> = {}): WorkerLaunchRequest {
  return cpuRequest({ accelerator: 'cuda', vramMib: 2048, ...overrides })
}

describe('launch — ruta CPU', () => {
